<?php
require_once __DIR__.'/auth.php'; require_login(); $activeAdmin='guia';
$pedFile=dirname(__DIR__).'/data/guia_pedidos.json'; $empFile=dirname(__DIR__).'/data/empresas.json'; function rj($f){ if(!file_exists($f)) return []; $d=json_decode(file_get_contents($f),true); return is_array($d)?$d:[];} function sj($f,$d){ file_put_contents($f,json_encode(array_values($d),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),LOCK_EX);} $ped=rj($pedFile); $emp=rj($empFile);
if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$_POST['action']??''; $id=$_POST['id']??''; foreach($ped as $k=>$p){ if(($p['id']??'')===$id){ if($action==='approve'){ $p['approved_at']=date('c'); $p['status']='publicado'; $emp[]=['name'=>$p['company']??'Empresa','area'=>$p['category']??'Serviços','desc'=>$p['description']??'','phone'=>$p['whatsapp']??'','instagram'=>$p['instagram']??'','site'=>$p['link']??'','image'=>$p['image']??'','city'=>$p['city']??'']; unset($ped[$k]); sj($empFile,$emp); sj($pedFile,$ped); header('Location: guia-comercial.php?approved=1'); exit; } if($action==='delete'){ unset($ped[$k]); sj($pedFile,$ped); header('Location: guia-comercial.php?deleted=1'); exit; } } } }
function h($v){ return htmlspecialchars((string)$v); } ?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Guia Comercial Admin</title><link rel="stylesheet" href="admin.css?v=41"></head><body><div class="admin"><?php include __DIR__.'/_menu.php'; ?><main class="main"><div class="top"><div><span class="eyebrow">Empresas</span><h1>Guia Comercial</h1></div><a class="btn secondary" target="_blank" href="../guia.php">Ver guia</a></div><?php if(isset($_GET['approved'])):?><div class="notice">Empresa aprovada e publicada.</div><?php endif; ?><div class="box"><h2>Solicitações recebidas</h2><?php if(!$ped): ?><p>Nenhum pedido pendente.</p><?php endif; ?><?php foreach(array_reverse($ped) as $p): ?><div class="box"><h2><?=h($p['company']??'Empresa')?></h2><p><b>Categoria:</b> <?=h($p['category']??'')?> • <b>Cidade:</b> <?=h($p['city']??'')?></p><p><?=h($p['description']??'')?></p><p><b>WhatsApp:</b> <?=h($p['whatsapp']??'')?> • <b>Instagram:</b> <?=h($p['instagram']??'')?></p><p><b>Comprovante:</b> <?=h($p['receipt']??'Não enviado')?> • <b>Imagem:</b> <?=h($p['image']??'Não enviada')?></p><form method="post" class="actions"><?=tvs_csrf_field()?><input type="hidden" name="id" value="<?=h($p['id']??'')?>"><button class="btn" name="action" value="approve">Aprovar e publicar</button><button class="btn danger" name="action" value="delete" onclick="return confirm('Excluir solicitação?')">Excluir</button></form></div><?php endforeach; ?></div><div class="box"><h2>Empresas publicadas: <?=count($emp)?></h2></div></main></div></body></html>
